```python
def perform_arithmetic(num1, num2, operation):
    """Perform arithmetic operation on two numbers."""
    if operation not in ['+', '-', '*', '/']:
        raise ValueError("Invalid arithmetic operation. Choose from +, -, *, /")

    try:
        result = eval(f"{num1} {operation} {num2}")
    except (NameError, ZeroDivisionError):
        raise ValueError("Invalid input. Please provide two numbers and a valid arithmetic operation.")

    return result


if __name__ == "__main__":
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            operation = input("Enter the arithmetic operation (+, -, *, /): ")

            result = perform_arithmetic(num1, num2, operation)
            print(f"The result of {operation} is {result}.")

        except ValueError as e:
            print(e)
        else:
            break
```

This program will keep prompting the user for input until they provide valid numbers and an arithmetic operation.
